// Must match auction/src/merkle.ts and auction/src/memo.ts byte for byte:
//
//   commitment = sha256(claim_pubkey || salt)
//   leaf       = sha256(0x00 || commitment || tokens as u64 little-endian)
//   node       = sha256(0x01 || min(a, b) || max(a, b))
//
// tests/fixtures/merkle_vectors.json is generated by the TypeScript side, so a
// drift on either side fails the native tests.

// On chain this uses the sol_sha256 syscall; off chain, a native SHA-256.
use solana_sha256_hasher::hashv;

/// Longest proof accepted: enough for 2^32 allocations, and it bounds compute.
pub const MAX_PROOF_LEN: usize = 32;

pub fn commitment(claim_pubkey: &[u8; 32], salt: &[u8; 16]) -> [u8; 32] {
    hashv(&[&claim_pubkey[..], &salt[..]]).to_bytes()
}

pub fn leaf(commitment: &[u8; 32], tokens: u64) -> [u8; 32] {
    hashv(&[&[0u8][..], &commitment[..], &tokens.to_le_bytes()[..]]).to_bytes()
}

fn node(a: &[u8; 32], b: &[u8; 32]) -> [u8; 32] {
    let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
    hashv(&[&[1u8][..], &lo[..], &hi[..]]).to_bytes()
}

pub fn verify(leaf: [u8; 32], proof: &[[u8; 32]], root: &[u8; 32]) -> bool {
    if proof.len() > MAX_PROOF_LEN {
        return false;
    }
    let computed = proof.iter().fold(leaf, |h, sibling| node(&h, sibling));
    &computed == root
}
